package basics;

public class MultiplicationTable {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		  int value = 12;
		  System.out.println("Multiplication Table of 12");
	        for (int i = 1; i <= 10; i++) {
	            System.out.println(i + " * " + value + " = " + (i * value));
	        }
	}

}
